DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('private.base_role_links_resign()'::regprocedure) INTO d; IF strpos(d,'UPDATE public.org_assignments a')=0 OR strpos(d,'r.catalog_generation')>0 THEN RAISE EXCEPTION 'Unexpected signature-sync function; review required'; END IF; d:=replace(d,'WHERE s.role_id = NEW.id','WHERE s.role_id = NEW.id AND NEW.catalog_generation < 2'); EXECUTE d; END $patch$;